class Solution:
    def distinctPrimeFactors(self, nums):
        ps=set()
        for v in nums:
            d=2
            while d*d<=v:
                if v%d==0:
                    ps.add(d)
                    while v%d==0: v//=d
                d+=1
            if v>1: ps.add(v)
        return len(ps)

