class Solution {
public:
    int distinctPrimeFactors(vector<int>& nums){
        unordered_set<int> ps;
        for(int v:nums){
            for(int d=2;d*d<=v;d++) if(v%d==0){ps.insert(d);while(v%d==0)v/=d;}
            if(v>1)ps.insert(v);
        }
        return ps.size();
    }
};

